            position: 'fixed',
            inset: 0,
            background: 'rgba(2, 6, 23, 0.82)',
            zIndex: 9999,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            padding: '18px'
          }}
        >
          <div
            onClick={(e) => e.stopPropagation()}
            style={{
              maxWidth: 'min(1200px, 96vw)',
              maxHeight: '92vh',
              borderRadius: '12px',
              overflow: 'hidden',
              border: '1px solid rgba(255,255,255,0.25)',
              background: 'transparent'
            }}
