      if (!response.ok) {
        handleUnauthorizedAdminResponse(
          response,
          result?.error || result?.message || 'Unable to load bookings'
        );
      }
      setRecords(result?.bookings || []);
    } catch (err: any) {
      if (!silent) {
        setError(err?.message || 'Unable to load bookings');
