        mobile: '',
        checkinDate: '',
        checkoutDate: '',
        bookingPurpose: 'meeting',
        bookingPurposeOther: ''
      });
      await loadRecords();
      alert('Admin booking created without payment');
    } catch (err: any) {
      setError(err?.message || 'Unable to create admin booking');
    } finally {
      setSaving(false);
    }
  };

  const startEdit = (record: BookingRecord) => {
    setEditingId(record._id);
    setEditForm({
      name: record.name,
      mobile: record.mobile,
      bookingPurpose: (record.bookingPurpose || 'function') as 'meeting' | 'camp' | 'picnic' | 'function' | 'program' | 'other',
      bookingPurposeOther: record.bookingPurposeOther || '',
      checkinDate: new Date(record.checkinDate).toISOString().split('T')[0],
      checkoutDate: new Date(record.checkoutDate).toISOString().split('T')[0],
      paymentAmount: record.paymentAmount,
      paymentType: record.paymentType,
      totalAmount: record.totalAmount,
      discountType: record.discountType || 'none',
      discountValue: Number(record.discountValue || 0)
    });
  };

  const cancelEdit = () => {
    setEditingId(null);
  };

  const getComputedDiscount = () => {
    const total = Number(editForm.totalAmount) || 0;
    const value = Number(editForm.discountValue) || 0;
    if (editForm.discountType === 'percentage') {
      return Math.min((total * value) / 100, total);
    }
    if (editForm.discountType === 'flat') {
      return Math.min(value, total);
    }
    return 0;
  };

  const getComputedFinalAmount = () => {
    const total = Number(editForm.totalAmount) || 0;
    return Math.max(total - getComputedDiscount(), 0);
  };

  const saveEdit = async () => {
    if (!editingId) return;
    setSaving(true);
    setError('');
    try {
      const response = await apiFetch(`/bookings/${editingId}`, {
        method: 'PUT',
        headers: withAdminAuth(adminToken, { 'Content-Type': 'application/json' }),
        body: JSON.stringify(editForm)
      });
      const result = await parseJsonSafe(response);
      if (!response.ok) {
        handleUnauthorizedAdminResponse(
          response,
          result?.error || result?.message || 'Unable to update booking'
        );
      }
      setEditingId(null);
      await loadRecords();
    } catch (err: any) {
      setError(err?.message || 'Unable to update booking');
    } finally {
      setSaving(false);
    }
  };

  const openDeleteDialog = (bookingId: string, bookingName: string) => {
    setPendingDelete({ id: bookingId, name: bookingName });
    setDeleteReason('');
    setDeleteCustomReason('');
  };

  const closeDeleteDialog = () => {
    if (deleting) return;
    setPendingDelete(null);
    setDeleteReason('');
    setDeleteCustomReason('');
  };

  const confirmDeleteBooking = async () => {
    if (!pendingDelete) return;
    if (!deleteReason) {
      setError('Please select a delete reason');
      return;
    }
    if (deleteReason === 'Other' && !deleteCustomReason.trim()) {
      setError('Please enter custom delete reason');
      return;
    }

    setDeleting(true);
    setError('');
    try {
      const payload = {
        reason: deleteReason,
        customReason: deleteReason === 'Other' ? deleteCustomReason.trim() : ''
      };

      // Prefer POST endpoint so reason can be sent reliably.
      let response = await apiFetch(`/bookings/${pendingDelete.id}/delete`, {
        method: 'POST',
        headers: withAdminAuth(adminToken, { 'Content-Type': 'application/json' }),
        body: JSON.stringify(payload)
      });

      // Fallback to DELETE if POST route is unavailable.
      if (response.status === 404 || response.status === 405) {
        const query = new URLSearchParams({ reason: payload.reason }).toString();
        response = await apiFetch(`/bookings/${pendingDelete.id}?${query}`, {
          method: 'DELETE',
          headers: withAdminAuth(adminToken, { 'Content-Type': 'application/json' }),
          body: JSON.stringify(payload)
        });
      }

      const result = await parseJsonSafe(response);
      if (!response.ok) {
        handleUnauthorizedAdminResponse(
          response,
          result?.error || result?.message || 'Unable to delete booking'
        );
      }

      if (editingId === pendingDelete.id) {
        setEditingId(null);
      }
      closeDeleteDialog();
      await loadRecords();
    } catch (err: any) {
      setError(err?.message || 'Unable to delete booking');
    } finally {
      setDeleting(false);
    }
  };

  const bookedByDate: Record<string, string[]> = {};
  const bookedPaymentStateByDate: Record<string, 'booked' | 'full-paid'> = {};
  const bookedPendingByDate: Record<string, number> = {};
  records.forEach((record) => {
    if (record.status === 'canceled') return;
    const checkin = new Date(record.checkinDate);
    const checkout = new Date(record.checkoutDate);
    const targetTotal = Number(record.finalAmount ?? record.totalAmount);
    const paidAmount = Number(record.paymentAmount || 0);
    const pendingAmount = Math.max(targetTotal - paidAmount, 0);
    const isFullPaid = paidAmount >= targetTotal;
    const cursor = new Date(checkin);
    while (cursor < checkout) {
      const dateKey = cursor.toISOString().split('T')[0];
      if (!bookedByDate[dateKey]) {
        bookedByDate[dateKey] = [];
      }
      if (!bookedPendingByDate[dateKey]) {
        bookedPendingByDate[dateKey] = 0;
      }
      if (!bookedByDate[dateKey].includes(record.name)) {
        bookedByDate[dateKey].push(record.name);
      }
      bookedPendingByDate[dateKey] += pendingAmount;
      if (!bookedPaymentStateByDate[dateKey] || isFullPaid) {
        bookedPaymentStateByDate[dateKey] = isFullPaid ? 'full-paid' : 'booked';
      }
      cursor.setDate(cursor.getDate() + 1);
    }
  });

  const monthYearTitle = calendarMonth.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });
  const firstDay = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), 1);
  const lastDay = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 0);
  const prefix = firstDay.getDay();
  const totalDays = lastDay.getDate();

  const calendarCells: React.ReactNode[] = [];
  for (let i = 0; i < prefix; i++) {
    calendarCells.push(<div key={`blank-${i}`} />);
  }
  for (let day = 1; day <= totalDays; day++) {
    const date = new Date(calendarMonth.getFullYear(), calendarMonth.getMonth(), day);
    const dateKey = date.toISOString().split('T')[0];
    const names = bookedByDate[dateKey] || [];
    const pendingByDate = bookedPendingByDate[dateKey] || 0;
    const paymentState = bookedPaymentStateByDate[dateKey];
    const isBooked = names.length > 0;
    const isFullPaid = paymentState === 'full-paid';
    calendarCells.push(
      <div
        key={dateKey}
        className={`calendar-day-card admin-day-card ${isBooked ? 'is-booked' : 'is-available'}`}
        style={{
          minHeight: '84px',
          border: isBooked ? '2px solid #16a34a' : '1px solid #fecaca',
          borderRadius: '8px',
          padding: '6px',
          background: isBooked ? (isFullPaid ? '#16a34a' : '#ffffff') : '#fee2e2'
        }}
      >
        <div style={{ fontWeight: 700, fontSize: '0.85rem', marginBottom: '4px', color: isFullPaid ? '#ffffff' : '#333' }}>{day}</div>
        {isBooked ? (
          <>
            <div className="calendar-day-sub" style={{ fontSize: '0.72rem', color: isFullPaid ? '#ffffff' : '#166534', lineHeight: 1.3 }}>
              {names.join(', ')}
            </div>
            <div className="calendar-day-meta" style={{ fontSize: '0.7rem', color: isFullPaid ? '#ffffff' : '#b45309', lineHeight: 1.3, marginTop: '4px', fontWeight: 700 }}>
              Pending: Rs {pendingByDate}
            </div>
          </>
        ) : (
          <div className="calendar-day-sub" style={{ fontSize: '0.72rem', color: '#b91c1c' }}>Available</div>
        )}
      </div>
    );
  }

  const confirmedCount = records.filter((r) => r.status === 'confirmed').length;
  const todayStart = new Date();
  todayStart.setHours(0, 0, 0, 0);

  const activeRecords = records.filter((r) => r.status !== 'canceled');
  const pastRecords = activeRecords
    .filter((r) => new Date(r.checkoutDate) < todayStart)
    .sort((a, b) => new Date(b.checkinDate).getTime() - new Date(a.checkinDate).getTime());
  const upcomingRecords = activeRecords
    .filter((r) => new Date(r.checkoutDate) >= todayStart)
    .sort((a, b) => new Date(a.checkinDate).getTime() - new Date(b.checkinDate).getTime());
  const [isAdminSettingsOpen, setIsAdminSettingsOpen] = useState(false);
  const [activeAdminSettingsSection, setActiveAdminSettingsSection] = useState<null | 'management' | 'image-logo' | 'complain-feedback'>(null);
  const adminSettingsMenuRef = React.useRef<HTMLDivElement | null>(null);
  const dashboardTopRef = React.useRef<HTMLDivElement | null>(null);
  const bookingDetailsRef = React.useRef<HTMLDivElement | null>(null);
  const quickBookingRef = React.useRef<HTMLDivElement | null>(null);
  const offerComplainFeedbackRef = React.useRef<HTMLDivElement | null>(null);
  const managementImageHistoryRef = React.useRef<HTMLDivElement | null>(null);
  const imageLogoRef = React.useRef<HTMLDivElement | null>(null);
  const complainFeedbackRef = React.useRef<HTMLDivElement | null>(null);
  const totalBookingRef = React.useRef<HTMLDivElement | null>(null);
  const todayCheckinsCount = activeRecords.filter((r) => {
    const checkin = new Date(r.checkinDate);
    checkin.setHours(0, 0, 0, 0);
    return checkin.getTime() === todayStart.getTime();
  }).length;
  const pendingBalanceRecordsCount = activeRecords.filter((r) => {
    const finalAmount = Number(r.finalAmount ?? r.totalAmount ?? 0);
    const pendingAmount = Math.max(finalAmount - Number(r.paymentAmount || 0), 0);
    return pendingAmount > 0;
  }).length;
  const primaryUpcomingBooking = upcomingBookings[0] || null;
  const primaryUpcomingPendingAmount = primaryUpcomingBooking
    ? Math.max(
        Number(primaryUpcomingBooking.finalAmount ?? primaryUpcomingBooking.totalAmount ?? 0) -
          Number(primaryUpcomingBooking.paymentAmount || 0),
        0
      )
    : 0;
  const complaintPreviewItems = complainList.slice(0, 3);
  const summaryStamp = new Date().toLocaleString('en-IN', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
  const scrollToRef = (ref: React.RefObject<HTMLDivElement | null>) => {
    ref.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };
  const approveAllPendingPayments = async () => {
    if (!pendingApprovalRecords.length) return;
    for (const row of pendingApprovalRecords.slice(0, 5)) {
      await approveUserPayment(row);
    }
  };

  const openAdminSettingsSection = (section: 'management' | 'image-logo' | 'complain-feedback') => {
    setIsAdminSettingsOpen(false);
    setActiveAdminSettingsSection(section);
    const sectionRef =
      section === 'management'
        ? managementImageHistoryRef
        : section === 'image-logo'
          ? imageLogoRef
          : complainFeedbackRef;

    window.setTimeout(() => {
      sectionRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 60);
  };

  const closeAdminSettingsSection = () => {
    setActiveAdminSettingsSection(null);
  };

  React.useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (!adminSettingsMenuRef.current) return;
      if (!adminSettingsMenuRef.current.contains(event.target as Node)) {
        setIsAdminSettingsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleOutsideClick);
    return () => document.removeEventListener('mousedown', handleOutsideClick);
  }, []);

  return (
    <div className="page-frame admin-page" style={{ minHeight: '100vh', padding: '0' }}>
      <div className="admin-dashboard-wrap admin-v2-wrap" style={{ maxWidth: '1520px', margin: '0 auto', padding: '0 0 20px 0' }} ref={dashboardTopRef}>
        <div className="admin-v2-header">
          <div className="admin-v2-brand">
            {adminLogoUrl ? (
              <img
                src={adminLogoUrl}
                alt="Organization logo"
                style={{ width: '44px', height: '44px', borderRadius: '999px', border: '1px solid rgba(191, 219, 254, 0.6)', objectFit: 'cover', background: '#fff' }}
              />
            ) : (
              <div style={{ width: '44px', height: '44px', borderRadius: '999px', border: '1px dashed rgba(191, 219, 254, 0.9)', background: 'rgba(255,255,255,0.14)' }} title="Logo space" />
            )}
            <div>
              <h2 style={{ margin: 0, color: '#f8fafc', fontSize: '2rem', fontWeight: 700 }}>Jharkhand Chatriya Sangh</h2>
              <div style={{ color: 'rgba(226, 232, 240, 0.88)', marginTop: '2px', fontSize: '1.15rem' }}>Admin Dashboard</div>
            </div>
          </div>
          <div className="admin-v2-header-actions">
            <button className="admin-v2-top-btn is-active" onClick={() => scrollToRef(totalBookingRef)}>Dashboard</button>
            <button className="admin-v2-top-btn" onClick={() => scrollToRef(bookingDetailsRef)}>Bookings</button>
            <button className="admin-v2-top-btn" onClick={() => scrollToRef(quickBookingRef)}>Calendar</button>
            <div ref={adminSettingsMenuRef} className="settings-wrap" style={{ position: 'relative' }}>
              <button
                type="button"
                aria-label="Admin Settings"
                onClick={() => setIsAdminSettingsOpen((prev) => !prev)}
                className="admin-v2-top-btn"
              >
                Settings
              </button>
              {isAdminSettingsOpen && (
                <div
                  className="settings-menu"
                  style={{
                    position: 'absolute',
                    top: '44px',
                    right: 0,
                    minWidth: '220px',
                    background: '#ffffff',
                    border: '1px solid #e2e8f0',
                    borderRadius: '10px',
                    boxShadow: '0 12px 28px rgba(2, 6, 23, 0.18)',
                    padding: '6px',
                    zIndex: 60
                  }}
                >
                  <button
                    type="button"
                    className="settings-menu-item"
                    onClick={() => openAdminSettingsSection('management')}
                    style={{ width: '100%', border: 'none', background: 'transparent', textAlign: 'left', padding: '8px 10px', borderRadius: '8px', color: '#0f172a', fontSize: '0.9rem', cursor: 'pointer' }}
                  >
                    Management
                  </button>
                  <button
                    type="button"
                    className="settings-menu-item"
                    onClick={() => openAdminSettingsSection('image-logo')}
                    style={{ width: '100%', border: 'none', background: 'transparent', textAlign: 'left', padding: '8px 10px', borderRadius: '8px', color: '#0f172a', fontSize: '0.9rem', cursor: 'pointer' }}
                  >
                    Add Image and Logo
                  </button>
                  <button
                    type="button"
                    className="settings-menu-item"
                    onClick={() => openAdminSettingsSection('complain-feedback')}
                    style={{ width: '100%', border: 'none', background: 'transparent', textAlign: 'left', padding: '8px 10px', borderRadius: '8px', color: '#0f172a', fontSize: '0.9rem', cursor: 'pointer' }}
                  >
                    Complain and Feedback
                  </button>
                </div>
              )}
            </div>
            <button className="admin-v2-ghost-btn" onClick={onBackToBooking}>Home</button>
            <button className="admin-v2-ghost-btn is-danger" onClick={onLogout}>Logout</button>
          </div>
        </div>

        <div className="admin-v2-layout">
          <aside className="admin-v2-sidebar">
            <div className="admin-v2-side-title">Dashboard</div>
            <button className="admin-v2-side-link active" onClick={() => scrollToRef(totalBookingRef)}>Dashboard</button>
            <button className="admin-v2-side-link" onClick={() => scrollToRef(bookingDetailsRef)}>Bookings</button>
            <button className="admin-v2-side-link" onClick={() => scrollToRef(quickBookingRef)}>Calendar</button>
            <button className="admin-v2-side-link" onClick={() => openAdminSettingsSection('management')}>Payments</button>
            <button className="admin-v2-side-link" onClick={() => openAdminSettingsSection('complain-feedback')}>Reports</button>
            <div className="admin-v2-side-title">History</div>
            <button className="admin-v2-side-link" onClick={() => scrollToRef(offerComplainFeedbackRef)}>Fast Records</button>
            <button className="admin-v2-side-link" onClick={() => scrollToRef(complainFeedbackRef)}>Bookings Security</button>
          </aside>

          <div className="admin-v2-workspace">
            <div className="admin-v2-summary-strip">
              <div>
                {primaryUpcomingBooking ? (
                  <span>
                    <strong>Allotment No: {primaryUpcomingBooking.bookingCode || '----'}</strong>
                    {'  |  '}
                    Check-in: {new Date(primaryUpcomingBooking.checkinDate).toLocaleDateString('en-IN')}
                    {'  |  '}
                    Check-out: {new Date(primaryUpcomingBooking.checkoutDate).toLocaleDateString('en-IN')}
                  </span>
                ) : (
                  <span><strong>Allotment No: ----</strong> | No upcoming booking</span>
                )}
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap' }}>
                <strong style={{ color: '#c2410c' }}>Pending Rs {primaryUpcomingPendingAmount.toLocaleString('en-IN')}</strong>
                <span style={{ color: '#64748b', fontSize: '0.82rem', fontWeight: 700 }}>{summaryStamp}</span>
                <span style={{ color: '#94a3b8', fontSize: '1.1rem', fontWeight: 700 }}>&#8250;</span>
              </div>
            </div>

            <div className="admin-v2-top-grid">
              <div>
                <div className="admin-v2-kpi-grid" ref={totalBookingRef}>
                  <div className="admin-v2-kpi-card is-blue">
                    <span>Total Bookings</span>
                    <strong>{records.length}</strong>
                  </div>
                  <div className="admin-v2-kpi-card is-teal">
                    <span>Confirmed</span>
                    <strong>{confirmedCount}</strong>
                  </div>
                  <div className="admin-v2-kpi-card is-amber">
                    <span>Pending Payment</span>
                    <strong>{pendingBalanceRecordsCount}</strong>
                  </div>
                </div>

                <div className="admin-v2-mini-kpi-row">
                  <div className="admin-v2-mini-kpi">
                    <span>Pending Payment Requests</span>
                    <strong>{pendingApprovalCount}</strong>
                  </div>
                  <div className="admin-v2-mini-kpi">
                    <span>Today's Check-ins</span>
                    <strong>{todayCheckinsCount}</strong>
                  </div>
                  <div className="admin-v2-actions-wrap">
                    <button onClick={() => { void loadRecords(); }} className="admin-v2-small-action">Refresh</button>
                    <button onClick={exportExcel} className="admin-v2-small-action">Export</button>
                    <label className="admin-v2-small-action upload">
                      Import
                      <input
                        type="file"
                        accept=".xlsx,.xls"
                        style={{ display: 'none' }}
                        onChange={(e) => {
                          const file = e.target.files?.[0];
                          if (file) {
                            importExcel(file);
                            e.currentTarget.value = '';
                          }
                        }}
                      />
                    </label>
                    <button onClick={shareBookings} className="admin-v2-small-action">Share</button>
                  </div>
                </div>

                <div className="admin-card admin-v2-calendar-panel">
                  <div className="admin-v2-calendar-head">
                    <h3 style={{ margin: 0, color: '#0f172a', fontSize: '2rem' }}>{monthYearTitle}</h3>
                    <div style={{ display: 'flex', gap: '8px' }}>
                      <button onClick={() => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() - 1, 1))} className="admin-v2-cal-btn">Prev</button>
                      <button onClick={() => setCalendarMonth(new Date(calendarMonth.getFullYear(), calendarMonth.getMonth() + 1, 1))} className="admin-v2-cal-btn">Next</button>
                    </div>
                  </div>
                  <div className="calendar-weekdays-grid admin-v2-weekdays" style={{ display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))' }}>
                    <div>Sun</div>
                    <div>Mon</div>
                    <div>Tue</div>
                    <div>Wed</div>
                    <div>Thu</div>
                    <div>Fri</div>
                    <div>Sat</div>
                  </div>
                  <div className="calendar-days-grid admin-v2-days" style={{ display: 'grid', gridTemplateColumns: 'repeat(7, minmax(0, 1fr))', gap: '4px' }}>
                    {calendarCells}
                  </div>
                  <div className="admin-v2-calendar-legend">
                    <span><i className="dot booked" />Booked</span>
                    <span><i className="dot fullpaid" />Booked Paid</span>
                    <span><i className="dot pending" />Pending</span>
                    <span><i className="dot unavailable" />Unavailable</span>
                  </div>
                </div>
              </div>

              <div className="admin-v2-side-widgets">
                <div className="admin-v2-widget-card">
                  <div className="admin-v2-widget-title">Pending Payment Requests</div>
                  <button
                    onClick={() => {
                      void approveAllPendingPayments();
                    }}
                    disabled={!pendingApprovalRecords.length}
                    className="admin-v2-approve-all-btn"
                  >
                    Approve All
                  </button>
                  {!pendingApprovalRecords.length ? (
                    <div className="admin-v2-widget-empty">No pending payment requests.</div>
                  ) : (
                    <div className="admin-v2-widget-list">
                      {pendingApprovalRecords.slice(0, 3).map((row) => (
                        <div key={`pending-approval-${row._id}`} className="admin-v2-widget-item">
                          <div>
                            <strong>Allotment {row.bookingCode || '----'}</strong>
                            <div>{row.name || 'Guest'}</div>
                            <small>{new Date(row.checkinDate).toLocaleDateString('en-IN')}</small>
                          </div>
                          <div style={{ display: 'grid', gap: '6px' }}>
                            <button onClick={() => { void approveUserPayment(row); }} className="admin-v2-inline-approve">Approve</button>
                            <button onClick={() => { void rejectUserPayment(row); }} className="admin-v2-inline-reject">Reject</button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>

                <div className="admin-v2-widget-card">
                  <div className="admin-v2-widget-title">Customer Complaints</div>
                  {!complaintPreviewItems.length ? (
                    <div className="admin-v2-widget-empty">No complaints available.</div>
                  ) : (
                    <div className="admin-v2-widget-list">
                      {complaintPreviewItems.map((item) => (
                        <div key={`complaint-preview-${item.id}`} className="admin-v2-complaint-item">
                          <div style={{ fontWeight: 700, color: '#0f172a' }}>{item.name || 'Guest'}</div>
                          <div style={{ color: '#475569', marginTop: '2px' }}>{item.message}</div>
                          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '6px', alignItems: 'center' }}>
                            <small style={{ color: '#64748b' }}>{new Date(item.createdAt).toLocaleDateString('en-IN')}</small>
                            <button onClick={() => resolveAndWhatsappComplain(item)} className="admin-v2-inline-approve">Resolve</button>
                          </div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </div>

            {pendingApprovalCount > 0 && (
              <div className="admin-v2-notice-strip">
                Notification: amount of Rs {latestPendingRequestAmount} was created{latestPendingRequestDetails}
              </div>
            )}
            {!activeAdminSettingsSection && (
              <div className="admin-v2-notice-hint">
                Open <strong>Settings</strong> to manage: <strong>Management</strong>, <strong>Add Image and Logo</strong>, and <strong>Complain and Feedback</strong>.
              </div>
            )}
          </div>
        </div>

        <div className="admin-v2-legacy-main">

        {activeAdminSettingsSection === 'management' && (
        <div className="admin-card admin-v2-full-width" ref={managementImageHistoryRef} style={{ background: 'rgba(255,255,255,0.95)', borderRadius: '16px', padding: '14px', boxShadow: '0 12px 26px rgba(0,0,0,0.12)', marginBottom: '14px', order: 5 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '10px', marginBottom: '10px' }}>
            <h3 style={{ marginTop: 0, marginBottom: 0, color: '#0f172a' }}>MANAGEMENT</h3>
            <button
              type="button"
              onClick={closeAdminSettingsSection}
              style={{ border: '1px solid #cbd5e1', background: '#f8fafc', color: '#334155', borderRadius: '8px', padding: '6px 10px', cursor: 'pointer', fontWeight: 700 }}
            >
              Close
            </button>
          </div>
          <div className="admin-management-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(230px, 1fr))', gap: '12px' }}>
