                            if (prev.length <= 1) return [{ name: '', profileType: '', contact: '' }];
                            return prev.filter((_, i) => i !== idx);
                          })
                        }
                        style={{ border: 'none', borderRadius: '8px', padding: '8px 10px', background: '#dc2626', color: '#fff', cursor: 'pointer', fontWeight: 700 }}
