                                Resolve & WhatsApp
                              </button>
                              <button
                                type="button"
                                onClick={() => removeComplain(item.id)}
                                style={{ border: 'none', borderRadius: '7px', padding: '5px 8px', background: '#dc2626', color: '#fff', cursor: 'pointer', fontWeight: 700, fontSize: '0.78rem' }}
                              >
                                Remove
                              </button>
                            </div>
                          </div>
