                      <span style={{ minWidth: '20px', height: '20px', borderRadius: '999px', padding: '0 6px', background: '#dc2626', color: '#fff', fontSize: '0.74rem', fontWeight: 700, display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }}>
