                          >
                            {'\u2715'}
                          </button>
                          <div style={{ fontWeight: 700, color: '#0f172a' }}>Guest Name: {item.name || 'Guest'}</div>
                          <div style={{ marginTop: '2px', color: '#0f172a' }}>Phone Number: {item.phone || 'Not available'}</div>
                          <div style={{ marginTop: '3px' }}>{item.message}</div>
