        {activeAdminSettingsSection === 'image-logo' && (
        <div className="admin-card admin-v2-full-width" ref={imageLogoRef} style={{ background: 'rgba(255,255,255,0.95)', borderRadius: '16px', padding: '14px', boxShadow: '0 12px 26px rgba(0,0,0,0.12)', marginBottom: '14px', order: 6 }}>
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: '10px', marginBottom: '10px' }}>
