                style={{ border: 'none', borderRadius: '8px', width: '40px', height: '40px', background: '#1d4ed8', color: 'white', cursor: 'pointer', display: 'inline-flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem' }}
