        <div className="admin-card admin-v2-message-card" ref={offerComplainFeedbackRef} style={{ background: 'rgba(255,255,255,0.95)', borderRadius: '16px', padding: '14px', boxShadow: '0 12px 26px rgba(0,0,0,0.12)', marginBottom: '14px', order: 7 }}>
          <h3 style={{ marginTop: 0, color: '#0f172a' }}>OFFER MESSAGE</h3>
