              value={selectedOfferBooking ? selectedOfferPendingAmount : ''}
              readOnly
              placeholder="Pending amount"
              style={{ padding: '10px', borderRadius: '8px', border: '1px solid #cbd5e1', background: '#f8fafc' }}
            />
          </div>
