          </div>
          {selectedOfferBooking && (
            <div style={{ marginBottom: '10px', fontSize: '0.86rem', color: selectedOfferAdminApproved ? '#166534' : selectedOfferAdminRejected ? '#b91c1c' : '#b45309', fontWeight: 600 }}>
