              Copy Offer Message
            </button>
            <button
              onClick={sendOfferMessageToWhatsapp}
              disabled={!selectedOfferAdminApproved}
              style={{
                border: 'none',
                borderRadius: '8px',
                padding: '10px 12px',
                background: selectedOfferAdminApproved ? '#16a34a' : '#94a3b8',
