                        <div style={{ marginTop: '3px', color: '#dc2626', fontWeight: 700 }}>Issue : {item.message}</div>
                        <div style={{ marginTop: '6px', display: 'flex', gap: '6px', flexWrap: 'wrap' }}>
                          <button
